INSERT INTO "PreGeneratedQuestion" (id, "questionType", system, difficulty, "questionData", "questionOrder", "taskCategory", "validationStatus", "generatedAt")
VALUES
('q-tax-cv-021', 'clinical-vignette', 'CV', 'hard', '{"question":"A 52-year-old male with uncontrolled diabetes (HbA1c 11.2%) and hypertension presents with exertional chest discomfort. EKG shows Q waves in the lateral leads suggesting prior MI. Stress test shows moderate ischemia in LAD territory. Echocardiography reveals EF 35% with apical akinesis. He is currently on aspirin, lisinopril, and atorvastatin. At cardiac catheterization, significant three-vessel CAD is found. What is the best revascularization strategy?","options":["A. Percutaneous coronary intervention (PCI) of all three vessels","B. Coronary artery bypass graft (CABG) surgery","C. Medical management with optimization of medical therapy","D. Single-vessel PCI to the most critical lesion"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has three-vessel CAD with reduced EF (35%), prior MI, and significant ischemia. Per CABG vs PCI trials (SYNTAX, CREDO-Diabetes), CABG is superior for three-vessel disease and/or left main disease, particularly in patients with diabetes and reduced EF. Option A: PCI of all three vessels in this patient has worse outcomes compared to CABG due to the complexity. Option C: medical therapy alone is insufficient for significant three-vessel disease with viable ischemic myocardium and reduced EF. Option D: single-vessel intervention inadequately addresses three-vessel pathology. This patient needs complete revascularization, best achieved with CABG.","conditionName":"Three-Vessel Coronary Artery Disease","system":"CV","subcategory":"Acute Coronary Syndrome","tags":["CV","CAD","three-vessel","CABG","revascularization"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),
('q-tax-cv-022', 'clinical-vignette', 'CV', 'hard', '{"question":"A 68-year-old woman with a history of rheumatic heart disease presents with dyspnea at rest and orthopnea. Echocardiography shows a mitral valve area of 0.9 cm² and a mean gradient of 18 mmHg. Atrial fibrillation with RVR (130 bpm) is present. PA pressure is 55 mmHg. She is on metoprolol 50 mg BID and digoxin. What is the most appropriate immediate intervention?","options":["A. Increase digoxin dose to achieve better rate control","B. Add verapamil to current regimen for additional rate control","C. Urgent percutaneous mitral balloon commissurotomy","D. Diuretics and IV nitroprusside for hemodynamic stabilization"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This patient has severe mitral stenosis (area 0.9 cm² is critical; normal >4 cm²) complicated by acute decompensation with RVR and pulmonary hypertension. She requires definitive mitral stenosis relief. Percutaneous mitral balloon commissurotomy is the intervention of choice for symptomatic mitral stenosis with favorable anatomy (pliable valve, no thrombus, no significant MR). This provides rapid hemodynamic improvement. Option A: increasing digoxin alone does not relieve the stenotic lesion. Option B: verapamil can worsen HF in this setting. Option D: temporizing measures delay necessary definitive therapy. Commissurotomy relieves the obstruction causing her acute decompensation.","conditionName":"Severe Mitral Stenosis","system":"CV","subcategory":"Valvular Disease","tags":["CV","mitral-stenosis","commissurotomy","rheumatic","AF"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),
('q-tax-cv-023', 'clinical-vignette', 'CV', 'hard', '{"question":"A 45-year-old male with a family history of sudden cardiac death presents with recurrent syncopal episodes. EKG reveals prolonged QTc (520 ms). Genetic testing identifies a mutation in KCNQ1 (potassium channel gene) consistent with long QT syndrome (LQTS). He is currently on no medications. What is the most appropriate next step?","options":["A. Serial EKG monitoring every 3 months with reassurance","B. Beta-blocker therapy; if recurrent syncope occurs, ICD placement","C. Avoid QT-prolonging medications and initiate magnesium supplementation","D. Electrophysiology consultation for risk stratification and consideration of ICD"],"correctAnswer":"D","correctAnswerIndex":0,"explanation":"This patient has genetically confirmed LQTS with symptoms (syncope—marker of high risk for torsades de pointes and sudden death). His risk is highest due to family history of sudden death and symptomatic presentation. Option D is correct: EPS evaluation for risk stratification and ICD placement, which reduces sudden death risk. Beta-blockers (Option B) are first-line therapy and should be initiated, but symptomatic LQTS with high-risk features warrants ICD. Option A: observation is inadequate given his high-risk features. Option C: avoiding triggers is part of management but does not address lethal arrhythmia risk. Early ICD placement is appropriate in this genetic LQTS patient with symptoms.","conditionName":"Long QT Syndrome","system":"CV","subcategory":"Arrhythmias","tags":["CV","LQTS","genetic","syncope","ICD","sudden-death"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'professional', 'pending', NOW()),
('q-tax-cv-024', 'clinical-vignette', 'CV', 'hard', '{"question":"A 56-year-old female with a history of prior STEMI (2 years ago, treated with PCI) presents with gradually worsening dyspnea and orthopnea. EF is 30%. She is on aspirin, clopidogrel (due to drug-eluting stent), lisinopril, carvedilol, and spironolactone. Recent troponin is normal. BNP is 680 pg/mL. She reports compliance with all medications. What is the most critical additional therapy to add for mortality reduction?","options":["A. SGLT2 inhibitor (dapagliflozin or empagliflozin)","B. Ivabradine for heart rate reduction","C. Hydralazine and isosorbide dinitrate","D. Milrinone infusion for inotropy"],"correctAnswer":"A","correctAnswerIndex":0,"explanation":"This post-MI patient with systolic HF (EF 30%) is on guideline-directed medical therapy (GDMT) but is missing SGLT2 inhibitors, which have proven mortality benefit in HF with reduced EF independent of diabetes status. SGLT2i (dapagliflozin, empagliflozin) reduce mortality and HF hospitalizations in systolic HF. Option B (ivabradine): used when heart rate >70 on optimal beta-blocker, may provide symptomatic benefit but less robust mortality data. Option C (hydralazine + nitrate): proven benefit in African Americans or ACE-I intolerant patients, not needed here. Option D (milrinone): worsens outcomes chronically. SGLT2 inhibitor addition is the most evidence-based next step for mortality reduction.","conditionName":"Ischemic Cardiomyopathy - Post-MI","system":"CV","subcategory":"Heart Failure","tags":["CV","HF","post-MI","SGLT2i","mortality-reduction"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'pharmaceutical', 'pending', NOW()),
('q-tax-cv-025', 'clinical-vignette', 'CV', 'hard', '{"question":"A 70-year-old man with chronic atrial fibrillation (rate-controlled on diltiazem) and CHA2DS2-VASc score of 4 presents with acute dyspnea. Chest X-ray shows pulmonary edema. His current medications are diltiazem 120 mg daily, warfarin (INR 2.2), and furosemide 40 mg daily. Echocardiography is planned but not yet completed. BP is 88/56. What is the most appropriate immediate management?","options":["A. Initiate IV heparin; hold warfarin until cardiology consultation","B. Synchronized external cardioversion after brief sedation","C. Increase diltiazem and furosemide doses","D. Immediate direct current (DC) cardioversion under general anesthesia"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient is hemodynamically unstable (BP 88/56) with AF and acute pulmonary edema. AF with rapid ventricular response in the setting of acute HF and hypotension requires urgent rate control. Synchronized electrical cardioversion (not defibrillation) is appropriate for hemodynamically unstable AF and will restore sinus rhythm, improving diastolic filling and cardiac output. Option A (heparin): anticoagulation is important but does not address acute hemodynamic instability. Option C: drugs will not achieve adequate rate control rapidly enough given hypotension. Option D (DC under GA): requires more time; synchronized cardioversion can be done with lighter sedation. Immediate cardioversion is life-saving in this scenario.","conditionName":"Atrial Fibrillation - Hemodynamically Unstable","system":"CV","subcategory":"Arrhythmias","tags":["CV","AF","cardioversion","hemodynamic-instability","acute-HF"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),
('q-tax-cv-026', 'clinical-vignette', 'CV', 'hard', '{"question":"A 54-year-old male with a history of myocardial infarction develops sudden acute chest pain and dyspnea 5 days post-MI. Examination reveals a new holosystolic murmur at the left sternal border, elevated JVP, and bilateral crackles. Echocardiography shows an 8 mm defect in the ventricular septum with left-to-right shunt and RA/RV dilation. What is the most appropriate management?","options":["A. Diuretics, vasodilators, and reassess in 24 hours","B. Immediate surgical repair with cardiopulmonary bypass","C. Percutaneous device closure via cardiac catheterization","D. Medical therapy until septal fibrosis allows delayed surgical repair (4-6 weeks)"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This is a post-MI ventricular septal defect (VSD), an acute mechanical complication of MI. The patient is hemodynamically compromised (elevated JVP, pulmonary edema, new murmur). Post-MI VSDs have high mortality and require urgent surgical repair, ideally within 24-48 hours of diagnosis. Medical optimization (diuretics, vasodilators, inotropes) supports the patient acutely but does not prevent catastrophic hemodynamic collapse. Option A: delaying surgery risks cardiogenic shock and death. Option C: percutaneous closure is emerging but surgical repair remains standard in acute post-MI VSD. Option D: waiting 4-6 weeks allows the septal inflammation to settle but risks hemodynamic deterioration during that period. Immediate surgery is appropriate here.","conditionName":"Post-MI Ventricular Septal Defect","system":"CV","subcategory":"Mechanical Complications","tags":["CV","VSD","post-MI","mechanical-complication","surgery"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'management', 'pending', NOW()),
('q-tax-cv-027', 'clinical-vignette', 'CV', 'hard', '{"question":"A 48-year-old woman with HIV infection (CD4 200) develops dyspnea and is found to have a large pericardial effusion (5 cm depth) on echo. She is hemodynamically stable with no signs of tamponade. Vital signs: BP 115/70, HR 92, RR 18. She is on antiretroviral therapy. What is the appropriate initial management?","options":["A. Emergent pericardiocentesis given the large effusion size","B. Diagnostic pericardiocentesis with fluid analysis, then tailor treatment based on results","C. Initiate anti-tuberculous therapy empirically and defer pericardiocentesis","D. Trial of high-dose NSAIDs and close observation"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient with advanced HIV (CD4 200) and large pericardial effusion requires diagnostic pericardiocentesis to determine the underlying cause (TB, opportunistic infection, malignancy, idiopathic). Fluid analysis (cultures, PCR, ADA, malignant cells, etc.) guides definitive treatment. Since she is hemodynamically stable without tamponade physiology, there is time for diagnostic assessment. Option A: draining without diagnosis misses treatable causes. Option C: TB is high on the differential in advanced HIV with pericardial effusion, but empiric therapy without confirmation risks over-treatment and misses other diagnoses. Option D: NSAIDs alone are inadequate for HIV-related pericarditis with large effusion. Diagnostic pericardiocentesis is the standard approach allowing targeted therapy.","conditionName":"Pericardial Effusion - HIV","system":"CV","subcategory":"Pericardial Disease","tags":["CV","pericardial-effusion","HIV","AIDS","pericardiocentesis"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'diagnostics', 'pending', NOW()),
('q-tax-cv-028', 'clinical-vignette', 'CV', 'hard', '{"question":"A 61-year-old man with diabetes, hypertension, and CKD (eGFR 28) develops acute worsening dyspnea. Chest X-ray shows diffuse bilateral opacities. EKG shows nonspecific ST changes. Troponin is 0.12 ng/mL (elevated). BP is 165/95. Patient is in acute cardiorenal syndrome (worsening renal function with acute HF). Which agent should be AVOIDED?","options":["A. Intravenous furosemide","B. ACE inhibitor (lisinopril)","C. Nitroglycerin infusion","D. Dobutamine infusion"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"In acute cardiorenal syndrome (HF with worsening renal function and hypercreatinemia), ACE inhibitors must be used cautiously or temporarily held because they reduce glomerular filtration pressure via efferent arteriole vasodilation, which can precipitate acute kidney injury. Once the patient is stabilized and fluid status is optimized, ACE-I can be reintroduced. Option A (furosemide): essential for volume overload despite CKD. Option C (nitrates): safe and reduce preload. Option D (dobutamine): can be used cautiously for inotropic support in cardiorenal syndrome. The key insight is that aggressive diuresis + vasodilation (without renal-protective agents) should precede ACE-I reinitiation to prevent AKI exacerbation.","conditionName":"Acute Cardiorenal Syndrome","system":"CV","subcategory":"Heart Failure","tags":["CV","cardiorenal-syndrome","CKD","AKI","acute-HF"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'pharmaceutical', 'pending', NOW()),
('q-tax-cv-029', 'clinical-vignette', 'CV', 'hard', '{"question":"A 75-year-old male with hypertension and mild reduced EF (45%) is noted to have new-onset paroxysmal atrial fibrillation with a CHA2DS2-VASc score of 5. He is currently on lisinopril and hydrochlorothiazide. He has no prior bleeding history. He is now in sinus rhythm but AF recurs. What is the most appropriate anticoagulation and rate control strategy?","options":["A. Warfarin with goal INR 2-3; rate control with diltiazem","B. Aspirin 325 mg daily as anticoagulation; rate control with metoprolol","C. Dabigatran or other DOAC; rate control with beta-blocker","D. No anticoagulation needed if sinus rhythm maintained; observe for recurrence"],"correctAnswer":"C","correctAnswerIndex":0,"explanation":"This patient with new AF and high stroke risk (CHA2DS2-VASc 5) requires anticoagulation regardless of rhythm. DOACs (dabigatran, rivaroxaban, apixaban, edoxaban) are preferred over warfarin in most patients given convenience, no monitoring, and superior efficacy in AF stroke prevention. Rate control with beta-blocker (metoprolol, atenolol) or calcium-channel blocker is appropriate. Option A (warfarin): acceptable but requires INR monitoring and dietary counseling. Option B (aspirin): inadequate for stroke prevention in AF; reserved for CHA2DS2-VASc 0-1. Option D: anticoagulation is indicated by stroke risk score, not rhythm control status.","conditionName":"Atrial Fibrillation - Anticoagulation","system":"CV","subcategory":"Arrhythmias","tags":["CV","AF","anticoagulation","DOAC","stroke-prevention"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'health_maintenance', 'pending', NOW()),
('q-tax-cv-030', 'clinical-vignette', 'CV', 'hard', '{"question":"A 58-year-old male smoker with HTN presents with sudden bilateral lower extremity weakness and back pain. He becomes acutely hypotensive (BP 95/50) with absent lower extremity pulses bilaterally. Emergent CT angiography shows acute aortic dissection extending from the ascending aorta through the descending thoracic aorta and into the abdominal aorta below the renal arteries. Which complication is occurring?","options":["A. Aortic rupture with exsanguination","B. Aortic dissection complicated by acute spinal cord ischemia (spinal artery compromise)","C. Mesenteric ischemia from dissection propagation","D. Acute MI from right coronary artery involvement"],"correctAnswer":"B","correctAnswerIndex":0,"explanation":"This patient has aortic dissection complicated by spinal cord ischemia. The bilateral leg weakness with hypotension and back pain, combined with the dissection extending through the descending aorta, indicates compromise of the arteries of Adamkiewicz (usually T9-T12) that supply the anterior spinal cord. This is a catastrophic complication of descending thoracic aortic dissection causing paraplegia. Option A (rupture): likely given hypotension but the imaging shows contained dissection. Option C (mesenteric ischemia): possible but the bilateral leg weakness points to cord ischemia. Option D (MI): less likely given bilateral findings. Spinal cord ischemia in dissection has devastating prognosis; recognition is critical for prognostication and discussion of goals of care.","conditionName":"Aortic Dissection - Spinal Cord Ischemia","system":"CV","subcategory":"Aortic Dissection","tags":["CV","aortic-dissection","spinal-cord-ischemia","paraplegia","complication"],"generatedWith":"taxonomy-gen-v1"}', 'third', 'professional', 'pending', NOW());